        const armState = room.memory.planMigration
            ? `migration ${room.memory.planMigration.mode}`
            : `placement only — run migratePlan("${adopt.room}") to arm the gradual migration`;
        logAlways(`planV2: ${adopt.room} adopted (${data.planHash || "no-hash"}) — ` +
            Object.keys(t)
