function areRoomsNormalToThisRoom(homeRoom, targetRoom) {
    let route = Game.map.findRoute(homeRoom, targetRoom);
    if (route && route !== -2 && route.length > 0) {
        for (let partOfRoute of route) {
            if (Game.map.getRoomStatus(partOfRoute.room).status !== "normal") {
                return false;
            }
        }
    }
    else {
        return false;
    }
    return true;
}

function data(room) {
    if (!room.memory.data) {
        room.memory.data = {};
    }
    if (!room.memory.data.DOB) {
        room.memory.data.DOB = 0;
    }
    if (!room.memory.data.DOBug) {
        room.memory.data.DOBug = 0;
    }
    if (room.controller.progress <= 200) {
        room.memory.data.DOBug = 0;
    }
    if (!room.memory.data.c_spawned) {
        room.memory.data.c_spawned = 0;
    }
    let data = room.memory.data;
    data.DOB += 1;
    data.DOBug += 1;
    room.memory.data = data;
}
