function linkNetworkDelivers(room, sourceId) {
    if (!room.storage)
        return false;
    const srcKey = sourceId || "*";
    if (!room.memory.linkHaulBySource)
        room.memory.linkHaulBySource = {};
    const rec = room.memory.linkHaulBySource[srcKey];
    if (rec && Game.time - (rec.t || 0) < 50) {
        return rec.v;
    }
    const links = room.find(FIND_MY_STRUCTURES, { filter: (s) => s.structureType == STRUCTURE_LINK });
    const hub = _.some(links, (l) => l.pos.inRangeTo(room.storage.pos, 2));
